export function gerarRegrasConciliacaoPadrao(empresaId: number, offsetConta = (empresaId - 1) * 100, offsetHist = (empresaId - 1) * 20): RegraConciliacao[] {
  const baseId = (empresaId - 1) * 20;
  return [
    { id: baseId + 1, empresaId, palavraChave: 'PIX RECEBIDO', contaDebitoId: offsetConta + 6, contaCreditoId: offsetConta + 11, historicoId: offsetHist + 1, complementoPadrao: 'Recebimento de cliente via PIX' },
    { id: baseId + 2, empresaId, palavraChave: 'TARIFA', contaDebitoId: offsetConta + 58, contaCreditoId: offsetConta + 6, historicoId: offsetHist + 4, complementoPadrao: 'Tarifa bancária mensal de manutenção' },
    { id: baseId + 3, empresaId, palavraChave: 'PAGTO FORNECEDOR', contaDebitoId: offsetConta + 30, contaCreditoId: offsetConta + 6, historicoId: offsetHist + 2, complementoPadrao: 'Quitação de títulos fornecedores' },
    { id: baseId + 4, empresaId, palavraChave: 'FOLHA', contaDebitoId: offsetConta + 26, contaCreditoId: offsetConta + 6, historicoId: offsetHist + 2, complementoPadrao: 'Pagamento líquido de salários e ordenados' },
    { id: baseId + 5, empresaId, palavraChave: 'PRO-LABORE', contaDebitoId: offsetConta + 26, contaCreditoId: offsetConta + 6, historicoId: offsetHist + 2, complementoPadrao: 'Retirada de pró-labore sócios' }
  ];
}

