function gerarParcelasPriceSeed(
  principal: number,
  taxaMensal: number,
  prazo: number,
  dtInicio: string
): ParcelaAmortizacao[] {
  const i = taxaMensal / 100;
  const pmt = principal * (i * Math.pow(1 + i, prazo)) / (Math.pow(1 + i, prazo) - 1);
  let saldo = principal;
  const parcelas: ParcelaAmortizacao[] = [];

  for (let n = 1; n <= prazo; n++) {
    const juros = saldo * i;
    const amort = pmt - juros;
    saldo = Math.max(0, saldo - amort);
    
    const d = new Date(dtInicio);
    d.setMonth(d.getMonth() + n);
    const dtVenc = d.toISOString().split('T')[0];
    const comp = dtVenc.slice(0, 7);

    parcelas.push({
      numeroParcela: n,
      dataVencimento: dtVenc,
      competencia: comp,
      valorPrestacao: Math.round(pmt * 100) / 100,
      amortizacaoPrincipal: Math.round(amort * 100) / 100,
      jurosEncargos: Math.round(juros * 100) / 100,
      saldoDevedorFinal: Math.round(saldo * 100) / 100,
      segregacao: n <= 12 ? 'CURTO_PRAZO' : 'LONGO_PRAZO',
      status: n <= 2 ? 'PAGA' : 'VINCENDA',
      apropriadoContabil: n <= 2
    });
  }
  return parcelas;
}

