  // DEMONSTRAÇÃO DAS MUTAÇÕES DO PATRIMÔNIO LÍQUIDO (DMPL - CPC 26) & DVA (CPC 09)
  // ----------------------------------------------------
  public getQuadroDmpl(empresaId: number, ano: number): QuadroDmpl {
    const empresa = this.empresas.find(e => e.id === empresaId) || this.empresas[0];
    const contas = this.getContas(empresaId);
    const lancsAno = this.lancamentos.filter(l => l.empresaId === empresaId && l.dataLancamento.startsWith(String(ano)));

    const contaCap = contas.find(c => c.id === 34 || c.classificacao === '2.03.01.001');
    const contaResLegal = contas.find(c => c.id === 36 || c.classificacao === '2.03.02.001');
    const contaLucrosAcum = contas.find(c => c.id === 37 || c.classificacao === '2.03.02.002');

    const capitalSocialBase = (contaCap?.saldoAnterior && contaCap.saldoAnterior > 0) ? contaCap.saldoAnterior : (empresa.capitalSocial || 0);
    const reservasLucrosInicial = contaResLegal?.saldoAnterior || 0;
    const lucrosAcumInicial = contaLucrosAcum?.saldoAnterior || 0;

    const aumentoCapital = contaCap ? Math.max(0, lancsAno.filter(l => l.contaCreditoId === contaCap.id).reduce((s, l) => s + l.valor, 0) - lancsAno.filter(l => l.contaDebitoId === contaCap.id).reduce((s, l) => s + l.valor, 0)) : 0;

    const dreLinhas = this.gerarDREConsolidada(empresaId);
    const lucroLinha = dreLinhas.find(l => l.descricao.includes('LUCRO LÍQUIDO'));
    const lucroLiquido = lucroLinha ? lucroLinha.valorConsolidado : 0;
    const reservaLegal = lucroLiquido > 0 ? Number((lucroLiquido * 0.05).toFixed(2)) : 0;
    const reservaEstatutaria = 0;
    const dividendos = contaLucrosAcum ? lancsAno.filter(l => l.contaDebitoId === contaLucrosAcum.id).reduce((s, l) => s + l.valor, 0) : 0;
    const lucrosRetidos = Number((lucroLiquido - reservaLegal - reservaEstatutaria - dividendos).toFixed(2));

    const linhas: LinhaDmpl[] = [
      {
        id: '1',
        descricao: `Saldos em 01/01/${ano}`,
        capitalSocial: capitalSocialBase,
        reservasCapital: 0,
        reservasLucros: reservasLucrosInicial,
        acoesTesouraria: 0,
        lucrosPrejuizosAcumulados: lucrosAcumInicial,
        totalPl: capitalSocialBase + reservasLucrosInicial + lucrosAcumInicial
      },
      {
        id: '2',
        descricao: 'Ajustes de Exercícios Anteriores (NBC TG 23)',
        capitalSocial: 0,
        reservasCapital: 0,
        reservasLucros: 0,
        acoesTesouraria: 0,
        lucrosPrejuizosAcumulados: 0,
        totalPl: 0
      },
      {
        id: '3',
        descricao: 'Aumento de Capital Social por Subscrição / Integralização',
        capitalSocial: aumentoCapital,
        reservasCapital: 0,
        reservasLucros: 0,
        acoesTesouraria: 0,
        lucrosPrejuizosAcumulados: 0,
        totalPl: aumentoCapital
      },
      {
        id: '4',
        descricao: `Resultado Líquido do Exercício de ${ano}`,
        capitalSocial: 0,
        reservasCapital: 0,
        reservasLucros: 0,
        acoesTesouraria: 0,
        lucrosPrejuizosAcumulados: lucroLiquido,
        totalPl: lucroLiquido
      },
      {
        id: '5',
        descricao: 'Constituição de Reserva Legal (5% Lei 6.404/76)',
        capitalSocial: 0,
        reservasCapital: 0,
        reservasLucros: reservaLegal,
        acoesTesouraria: 0,
        lucrosPrejuizosAcumulados: -reservaLegal,
        totalPl: 0
      },
      {
        id: '6',
        descricao: 'Constituição de Reserva Estatutária e Expansão',
        capitalSocial: 0,
        reservasCapital: 0,
        reservasLucros: reservaEstatutaria,
        acoesTesouraria: 0,
        lucrosPrejuizosAcumulados: -reservaEstatutaria,
        totalPl: 0
      },
      {
        id: '7',
        descricao: 'Distribuição de Dividendos / Lucros Distribuídos',
        capitalSocial: 0,
        reservasCapital: 0,
        reservasLucros: 0,
        acoesTesouraria: 0,
        lucrosPrejuizosAcumulados: -dividendos,
        totalPl: -dividendos
      },
      {
        id: '8',
        descricao: `Saldos Finais em 31/12/${ano}`,
        capitalSocial: capitalSocialBase + aumentoCapital,
        reservasCapital: 0,
        reservasLucros: reservasLucrosInicial + reservaLegal + reservaEstatutaria,
        acoesTesouraria: 0,
        lucrosPrejuizosAcumulados: lucrosAcumInicial + lucrosRetidos,
        totalPl: (capitalSocialBase + aumentoCapital) + (reservasLucrosInicial + reservaLegal + reservaEstatutaria) + (lucrosAcumInicial + lucrosRetidos)
      }
    ];

    const totalFinalPl = linhas[linhas.length - 1].totalPl;
    return { ano, empresaId, linhas, totalFinalPl };
  }

  public getDemonstracaoDva(empresaId: number, ano: number): DemonstracaoDva {
    const dreLinhas = this.gerarDREConsolidada(empresaId);
    const recLinha = dreLinhas.find(l => l.descricao.includes('RECEITA OPERACIONAL BRUTA'));
    const receitaBruta = recLinha ? recLinha.valorConsolidado : 0;
    const custosLinha = dreLinhas.find(l => l.descricao.includes('CUSTOS'));
    const custosInsumos = custosLinha ? custosLinha.valorConsolidado : 0;

    const lancsAno = this.lancamentos.filter(l => l.empresaId === empresaId && l.dataLancamento.startsWith(String(ano)));
    const servicosTerceiros = lancsAno.filter(l => l.contaDebitoId === 53 || l.contaDebitoId === 52).reduce((s, l) => s + l.valor, 0);
    const depreciacao = lancsAno.filter(l => l.contaDebitoId === 55).reduce((s, l) => s + l.valor, 0);

    const valorAdicionadoBruto = receitaBruta - custosInsumos - servicosTerceiros;
    const valorAdicionadoLiquido = valorAdicionadoBruto - depreciacao;
    const valorAdicionadoTotal = valorAdicionadoLiquido;

    const geracaoValor: ItemDva[] = [
      { codigo: '1', descricao: 'RECEITAS', nivel: 1, valor: receitaBruta },
      { codigo: '1.1', descricao: 'Venda de mercadorias, produtos e serviços', nivel: 2, valor: receitaBruta },
      { codigo: '2', descricao: 'INSUMOS ADQUIRIDOS DE TERCEIROS', nivel: 1, valor: custosInsumos + servicosTerceiros },
      { codigo: '2.1', descricao: 'Custos das mercadorias e produtos vendidos', nivel: 2, valor: custosInsumos },
      { codigo: '2.2', descricao: 'Materiais, energia e serviços de terceiros', nivel: 2, valor: servicosTerceiros },
      { codigo: '3', descricao: 'VALOR ADICIONADO BRUTO (1 - 2)', nivel: 1, valor: valorAdicionadoBruto },
      { codigo: '4', descricao: 'RETENÇÕES (Depreciação, amortização e exaustão)', nivel: 1, valor: depreciacao },
      { codigo: '5', descricao: 'VALOR ADICIONADO LÍQUIDO PRODUZIDO PELA ENTIDADE (3 - 4)', nivel: 1, valor: valorAdicionadoLiquido },
      { codigo: '6', descricao: 'VALOR ADICIONADO TOTAL A DISTRIBUIR', nivel: 1, valor: valorAdicionadoTotal }
    ];

    const despesasPessoal = lancsAno.filter(l => l.contaDebitoId === 49 || l.contaDebitoId === 50).reduce((s, l) => s + l.valor, 0);
    const impostosTotais = lancsAno.filter(l => [42, 43, 44, 45, 58, 60].includes(l.contaDebitoId || 0)).reduce((s, l) => s + l.valor, 0);
    const impostosFederais = Number((impostosTotais * 0.65).toFixed(2));
    const impostosEstaduais = Number((impostosTotais * 0.35).toFixed(2));
    const jurosAlugueis = lancsAno.filter(l => l.contaDebitoId === 51 || l.contaDebitoId === 57).reduce((s, l) => s + l.valor, 0);
    const lucrosAcionistas = Number((valorAdicionadoTotal - (despesasPessoal + impostosFederais + impostosEstaduais + jurosAlugueis)).toFixed(2));

    const distribuicaoValor: ItemDva[] = [
      { codigo: '7.1', descricao: 'PESSOAL & ENCARGOS (Salários, Benefícios e FGTS)', nivel: 1, valor: despesasPessoal },
      { codigo: '7.2', descricao: 'IMPOSTOS, TAXAS E CONTRIBUIÇÕES', nivel: 1, valor: impostosFederais + impostosEstaduais },
      { codigo: '7.2.1', descricao: 'Federais (IRPJ, CSLL, PIS, COFINS, INSS Patronal)', nivel: 2, valor: impostosFederais },
      { codigo: '7.2.2', descricao: 'Estaduais e Municipais (ICMS, ISSQN)', nivel: 2, valor: impostosEstaduais },
      { codigo: '7.3', descricao: 'REMUNERAÇÃO DE CAPITAIS DE TERCEIROS (Juros e Aluguéis)', nivel: 1, valor: jurosAlugueis },
      { codigo: '7.4', descricao: 'REMUNERAÇÃO DE CAPITAIS PRÓPRIOS (Lucros Retidos e Dividendos)', nivel: 1, valor: lucrosAcionistas }
    ];

    return { ano, empresaId, geracaoValor, distribuicaoValor, valorAdicionadoTotal };
  }

