  // ==========================================
  // SPRINT 18: PER/DCOMP WEB (IN RFB nº 2.055/2021)
  // ==========================================

  public getCreditosPerDcomp(empresaId?: number): CreditoTributarioPerDcomp[] {
    const empId = empresaId || this.activeEmpresaId;
    return this.creditosPerDcomp.filter(c => c.empresaId === empId);
  }

  public salvarCreditoPerDcomp(item: Partial<CreditoTributarioPerDcomp> & { empresaId: number; tipoCredito: any; valorOriginal: number }): CreditoTributarioPerDcomp {
    const selic = item.taxaSelicAcumulada ?? 8.50;
    const juros = Math.round((item.valorOriginal * (selic / 100)) * 100) / 100;
    const totalAtualizado = Math.round((item.valorOriginal + juros) * 100) / 100;
    const utilizado = item.valorJaUtilizado || 0;
    const saldo = Math.max(0, totalAtualizado - utilizado);

    const cred: CreditoTributarioPerDcomp = {
      id: item.id || Date.now(),
      empresaId: item.empresaId,
      tipoCredito: item.tipoCredito,
      periodoApuracao: item.periodoApuracao || '2026-1T',
      dataPagamentoConstituicao: item.dataPagamentoConstituicao || new Date().toISOString().slice(0, 10),
      valorOriginal: item.valorOriginal,
      taxaSelicAcumulada: selic,
      valorJurosSelic: juros,
      valorTotalAtualizado: totalAtualizado,
      valorJaUtilizado: utilizado,
      saldoDisponivel: saldo,
      status: saldo === 0 ? 'TOTALMENTE_UTILIZADO' : (utilizado > 0 ? 'COMPENSADO_PARCIAL' : 'DISPONIVEL')
    };

    const idx = this.creditosPerDcomp.findIndex(c => c.id === cred.id);
    if (idx >= 0) {
      this.creditosPerDcomp[idx] = cred;
    } else {
      this.creditosPerDcomp.unshift(cred);
    }
    this.persistSnapshot();
    return cred;
  }

  public getDeclaracoesPerDcomp(empresaId?: number): DeclaracaoPerDcomp[] {
    const empId = empresaId || this.activeEmpresaId;
    return this.declaracoesPerDcomp.filter(d => d.empresaId === empId);
  }

  public salvarDeclaracaoPerDcomp(item: Partial<DeclaracaoPerDcomp> & { empresaId: number; creditoId: number; debitosCompensados: any[] }): DeclaracaoPerDcomp {
    const credito = this.creditosPerDcomp.find(c => c.id === item.creditoId);
    const valOriginal = credito ? credito.valorOriginal : (item.valorCreditoOriginal || 0);
    const valAtualizado = credito ? credito.valorTotalAtualizado : (item.valorCreditoAtualizadoSelic || 0);

    const totalDebitos = item.debitosCompensados.reduce((s, d) => s + (d.valorCompensado || d.valorTotalDebito || 0), 0);
    const saldoRemanescente = Math.max(0, valAtualizado - totalDebitos);

    const decl: DeclaracaoPerDcomp = {
      id: item.id || Date.now(),
      empresaId: item.empresaId,
      numeroPerDcomp: item.numeroPerDcomp || `PERDCOMP-${new Date().getFullYear()}-${String(this.declaracoesPerDcomp.length + 1).padStart(4, '0')}`,
      dataTransmissao: item.dataTransmissao || new Date().toISOString().slice(0, 10),
      tipoCredito: credito ? credito.tipoCredito : 'SALDO_NEGATIVO_IRPJ',
      creditoId: item.creditoId,
      valorCreditoOriginal: valOriginal,
      valorCreditoAtualizadoSelic: valAtualizado,
      debitosCompensados: item.debitosCompensados,
      totalDebitosCompensados: totalDebitos,
      saldoRemanescenteCredito: saldoRemanescente,
      integradoContabilidade: item.integradoContabilidade ?? false,
      numeroLoteContabil: item.numeroLoteContabil
    };

    if (credito) {
      credito.valorJaUtilizado += totalDebitos;
      credito.saldoDisponivel = Math.max(0, credito.valorTotalAtualizado - credito.valorJaUtilizado);
      credito.status = credito.saldoDisponivel === 0 ? 'TOTALMENTE_UTILIZADO' : 'COMPENSADO_PARCIAL';
    }

    const idx = this.declaracoesPerDcomp.findIndex(d => d.id === decl.id);
    if (idx >= 0) {
      this.declaracoesPerDcomp[idx] = decl;
    } else {
      this.declaracoesPerDcomp.unshift(decl);
    }
    this.persistSnapshot();
    return decl;
  }

  public integrarPerDcompContabil(declaracaoId: number): { sucesso: boolean; mensagem: string; numeroLote?: number } {
    const decl = this.declaracoesPerDcomp.find(d => d.id === declaracaoId);
    if (!decl) {
      return { sucesso: false, mensagem: 'Declaração PER/DCOMP não encontrada.' };
    }
    if (decl.integradoContabilidade && decl.numeroLoteContabil) {
      return { sucesso: false, mensagem: `Esta declaração já foi integrada no Lote nº ${decl.numeroLoteContabil}.` };
    }

    const empId = decl.empresaId;
    const proximoNumLote = this.lotes.reduce((m, l) => Math.max(m, l.numero), 0) + 1;
    const loteId = Date.now();

    const novoLote: LoteContabil = {
      id: loteId,
      empresaId: empId,
      numero: proximoNumLote,
      numeroLote: proximoNumLote,
      descricao: `Compensação Tributária PER/DCOMP nº ${decl.numeroPerDcomp}`,
      dataLote: decl.dataTransmissao,
      status: 'FECHADO',
      totalDebito: 0,
      totalCredito: 0
    };

    // Conta Crédito: Tributos a Recuperar (Ativo Circulante)
    const contaCreditoRecuperar = this.resolveConta(empId, {
      classificacoes: ['1.1.03.01', '1.1.03.05', '1.01.03.01'],
      nomes: ['impostos a recuperar', 'irpj a compensar', 'tributos a compensar'],
      fallbackId: 18
    });

    // Para cada débito compensado, debita o passivo correspondente
    let seq = 1;
    let totalD = 0;
    let totalC = 0;

    decl.debitosCompensados.forEach(deb => {
      const contaPassivoDebito = this.resolveConta(empId, {
        classificacoes: deb.tributo === 'PIS' ? ['2.1.04.03', '2.01.04.03'] :
                        deb.tributo === 'COFINS' ? ['2.1.04.04', '2.01.04.04'] :
                        deb.tributo === 'IRPJ' ? ['2.1.04.01', '2.01.04.01'] :
                        deb.tributo === 'CSLL' ? ['2.1.04.02', '2.01.04.02'] : ['2.1.04.05'],
        nomes: [`${deb.tributo.toLowerCase()} a recolher`, `${deb.tributo.toLowerCase()} a pagar`],
        fallbackId: 27
      });

      const lanc: LancamentoContabil = {
        id: Date.now() + seq,
        empresaId: empId,
        numeroPartida: seq,
        dataLancamento: decl.dataTransmissao,
        contaDebitoId: contaPassivoDebito,
        contaCreditoId: contaCreditoRecuperar,
        valor: deb.valorCompensado,
        historicoId: 1,
        complementoHistorico: `Compensação tributária ${deb.tributo} DARF Cód. ${deb.codigoReceitaDarf} ref. ${deb.periodoApuracao} via PER/DCOMP ${decl.numeroPerDcomp}`,
        tipoPartida: 'SIMPLES',
        usuarioId: 1,
        loteId: loteId,
        createdAt: new Date().toISOString()
      };

      this.lancamentos.push(lanc);
      totalD += deb.valorCompensado;
      totalC += deb.valorCompensado;
      seq++;
    });

    novoLote.totalDebito = Math.round(totalD * 100) / 100;
    novoLote.totalCredito = Math.round(totalC * 100) / 100;
    this.lotes.push(novoLote);

    decl.integradoContabilidade = true;
    decl.numeroLoteContabil = proximoNumLote;

    this.persistSnapshot();
    return {
      sucesso: true,
      mensagem: `PER/DCOMP ${decl.numeroPerDcomp} integrado com sucesso no Lote Contábil nº ${proximoNumLote} (Total: R$ ${totalD.toFixed(2)}).`,
      numeroLote: proximoNumLote
    };
  }

