  // -------------------------------------------------------------
  // PROTOCOLOS DE DOCUMENTOS & GUIAS (GEPROTOCOLO)
  // -------------------------------------------------------------
  public getProtocolos(empresaId: number): ProtocoloDocumento[] {
    return this.protocolos.filter(p => p.empresaId === empresaId);
  }

  public salvarProtocolo(proto: Omit<ProtocoloDocumento, 'id' | 'numeroProtocolo'> & { id?: number; numeroProtocolo?: string }): { success: boolean; id: number; numeroProtocolo: string } {
    const empId = proto.empresaId || this.activeEmpresaId;
    const ano = new Date().getFullYear();
    const existentesNoAno = this.protocolos.filter(p => p.numeroProtocolo.startsWith(`${ano}/`)).length;
    const proximoSeq = (existentesNoAno + 1).toString().padStart(5, '0');
    const numeroProtocolo = proto.numeroProtocolo || `${ano}/${proximoSeq}`;

    if (proto.id) {
      const idx = this.protocolos.findIndex(p => p.id === proto.id);
      if (idx !== -1) {
        this.protocolos[idx] = {
          ...proto,
          id: proto.id,
          empresaId: empId,
          numeroProtocolo: proto.numeroProtocolo || this.protocolos[idx].numeroProtocolo
        } as ProtocoloDocumento;
        this.persistSnapshot();
        return { success: true, id: proto.id, numeroProtocolo: this.protocolos[idx].numeroProtocolo };
      }
    }

    const novoId = Date.now();
    const novo: ProtocoloDocumento = {
      ...proto,
      id: novoId,
      empresaId: empId,
      numeroProtocolo,
      status: proto.status || 'EMITIDO'
    };

    this.protocolos.unshift(novo);
    this.persistSnapshot();
    return { success: true, id: novoId, numeroProtocolo };
  }

  public excluirProtocolo(id: number): boolean {
    const lenAntes = this.protocolos.length;
    this.protocolos = this.protocolos.filter(p => p.id !== id);
    if (this.protocolos.length !== lenAntes) {
      this.persistSnapshot();
      return true;
    }
    return false;
  }

  public atualizarStatusProtocolo(
    id: number,
    status: StatusProtocolo,
    dataHoraEntrega?: string,
    recebedor?: string
  ): boolean {
    const proto = this.protocolos.find(p => p.id === id);
    if (!proto) return false;

    proto.status = status;
    if (dataHoraEntrega) proto.dataHoraEntregaEfetiva = dataHoraEntrega;
    if (recebedor) proto.nomeContatoRecepcao = recebedor;

    this.persistSnapshot();
    return true;
  }

  // -------------------------------------------------------------
  // BOLETOS BANCÁRIOS & COBRANÇA DE HONORÁRIOS COM PIX (CNAB 240/400)
  // -------------------------------------------------------------
  public getBoletos(empresaId: number): BoletoBancario[] {
    return this.boletos.filter(b => b.empresaId === empresaId);
  }

  public salvarBoleto(boleto: Omit<BoletoBancario, 'id'> & { id?: number }): { success: boolean; id: number } {
    if (boleto.id) {
      const idx = this.boletos.findIndex(b => b.id === boleto.id);
      if (idx !== -1) {
        this.boletos[idx] = { ...boleto, id: boleto.id } as BoletoBancario;
        this.persistSnapshot();
        return { success: true, id: boleto.id };
      }
    }

    const novoId = Date.now();
    const novo: BoletoBancario = {
      ...boleto,
      id: novoId
    };
    this.boletos.unshift(novo);
    this.persistSnapshot();
    return { success: true, id: novoId };
  }

  public gerarBoletosParaFaturas(empresaId: number, competencia: string): { gerados: number; boletos: BoletoBancario[] } {
    const faturas = this.getFaturasHonorarios(competencia).filter(f => f.status === 'PENDENTE');
    const boletosGerados: BoletoBancario[] = [];

    for (const f of faturas) {
      const jaExiste = this.boletos.some(b => b.faturaId === f.id);
      if (jaExiste) continue;

      const ano = competencia.slice(0, 4);
      const mes = competencia.slice(5, 7);
      const seq = (this.boletos.length + boletosGerados.length + 1).toString().padStart(6, '0');
      const nossoNumero = `17/${ano}${mes}${seq}`;
      const valor = f.valorLiquidoFatura ?? f.valorTotal;
      const linhaDigitavel = `00190.00009 01428.${seq.slice(0, 5)}4 00010.245818 9 98750000${Math.round(valor * 100).toString().padStart(8, '0')}`;
      const codigoBarras = `0019998750000${Math.round(valor * 100).toString().padStart(8, '0')}00000001428590000001024581`;
      const pixPayload = `00020126580014br.gov.bcb.pix0136123e4567-e89b-12d3-a456-4266141740005204000053039865407${valor.toFixed(2)}5802BR5925AMIL CONTABILIDADE STUDIO6009SAO PAULO62070503***6304ABCD`;

      const novoBoleto: BoletoBancario = {
        id: Date.now() + boletosGerados.length + 1,
        faturaId: f.id,
        empresaId,
        codigoBanco: '001',
        nomeBanco: 'Banco do Brasil S.A.',
        agencia: '3420-5',
        contaCorrente: '10245-8',
        carteira: '17',
        numeroDocumento: `FAT-${f.id}`,
        nossoNumero,
        linhaDigitavel,
        codigoBarras,
        dataEmissao: new Date().toISOString().split('T')[0],
        dataVencimento: f.dataVencimento,
        valorBoleto: valor,
        multaAposVencimentoPercentual: 2.0,
        jurosMoraMensalPercentual: 1.0,
        pixCopiaECola: pixPayload,
        pixQrCodePayload: pixPayload,
        status: 'REGISTRADO_BANCO',
        instrucoesSacado: [
          'SR. CAIXA: NÃO RECEBER APÓS 30 DIAS DO VENCIMENTO.',
          'APÓS O VENCIMENTO COBRAR MULTA DE 2,00% E JUROS DE 1,00% AO MÊS.',
          'PAGÁVEL PREFERENCIALMENTE VIA PIX (QR CODE ABAIXO) OU EM QUALQUER AGÊNCIA BANCÁRIA.'
        ]
      };

      boletosGerados.push(novoBoleto);
      this.boletos.unshift(novoBoleto);
    }

    if (boletosGerados.length > 0) {
      this.persistSnapshot();
    }

    return { gerados: boletosGerados.length, boletos: boletosGerados };
  }

  public baixarBoletoLiquidar(id: number, dataPagamento?: string): { success: boolean; message: string } {
    const boleto = this.boletos.find(b => b.id === id);
    if (!boleto) return { success: false, message: 'Boleto não encontrado.' };

    boleto.status = 'LIQUIDADO_PAGO';
    boleto.dataPagamento = dataPagamento || new Date().toISOString().split('T')[0];
    boleto.valorPago = boleto.valorBoleto;

    // Atualiza a fatura vinculada
    const fatura = this.faturasHonorarios.find(f => f.id === boleto.faturaId);
    if (fatura) {
      fatura.status = 'PAGO';
      fatura.dataPagamento = boleto.dataPagamento;
    }

    this.persistSnapshot();
    return { success: true, message: `Boleto nº ${boleto.nossoNumero} baixado com sucesso como LIQUIDADO!` };
  }

