  public getEcfBlocoY(empresaId?: number, ano?: number): EcfBlocoYDados {
    const empId = empresaId || this.activeEmpresaId;
    const anoEx = ano || new Date().getFullYear();
    if (this.ecfBlocoY && this.ecfBlocoY.empresaId === empId && this.ecfBlocoY.anoExercicio === anoEx) {
      return this.ecfBlocoY;
    }
    return {
      empresaId: empId,
      anoExercicio: anoEx,
      registrosY540: [...SEED_ECF_BLOCO_Y.registrosY540],
      registrosY570: [...SEED_ECF_BLOCO_Y.registrosY570],
      registrosY600: [...SEED_ECF_BLOCO_Y.registrosY600],
      registroY672: { ...SEED_ECF_BLOCO_Y.registroY672 },
      dataAtualizacao: new Date().toISOString()
    };
  }

  public salvarEcfBlocoY(dados: EcfBlocoYDados): void {
    this.ecfBlocoY = dados;
    this.persistSnapshot();
  }

  public autoPreencherEcfBlocoY(empresaId?: number, ano?: number): EcfBlocoYDados {
    const empId = empresaId || this.activeEmpresaId;
    const anoEx = ano || new Date().getFullYear();
    const emp = this.getEmpresa(empId);

    // Y540 da receita de notas
    const notas = this.notasFiscais.filter(n => n.empresaId === empId && n.tipoOperacao === 'SAIDA');
    const totalVendas = notas.reduce((acc, n) => acc + (n.valorTotal || 0), 0);

    const y540: RegistroY540[] = [
      {
        id: `y540-${Date.now()}-1`,
        cnpjEstabelecimento: emp?.cnpj || '12.345.678/0001-90',
        codigoCnae: emp?.cnaePrincipal || '25.11-0/00',
        descricaoCnae: 'Atividade Principal Escriturada',
        receitaVendaBensProprios: 0,
        receitaVendaBensRevenda: totalVendas > 0 ? totalVendas : 420000.00,
        receitaPrestacaoServicos: 85000.00,
        receitaExportacao: 0,
        outrasReceitasOperacionais: 0,
        totalReceitaAtividade: (totalVendas > 0 ? totalVendas : 420000.00) + 85000.00
      }
    ];

    // Y600 do QSA
    const y600: RegistroY600[] = (emp?.socios && emp.socios.length > 0)
      ? emp.socios.map((s, idx) => ({
          id: `y600-${Date.now()}-${idx}`,
          paisResidencia: '105',
          indicadorPfPj: 'PF',
          cpfCnpj: s.cpf || '000.000.000-00',
          nomeSocioDirigente: s.nome,
          qualificacaoSocio: s.qualificacaoRFB || '49',
          percentualCapitalTotal: s.percentualCapital || 50,
          percentualCapitalVotante: s.percentualCapital || 50,
          rendimentoBrutoProlabore: s.retiraProLabore ? (s.valorProLabore || 5000) * 12 : 0,
          lucrosDividendosPagos: 150000.00 * ((s.percentualCapital || 50) / 100),
          jurosSobreCapitalProprio: 10000.00 * ((s.percentualCapital || 50) / 100),
          demaisRendimentos: 0,
          irrfRetidoSocio: s.retiraProLabore ? ((s.valorProLabore || 5000) * 12 * 0.15) : 0
        }))
      : [...SEED_ECF_BLOCO_Y.registrosY600];

    const novoBlocoY: EcfBlocoYDados = {
      empresaId: empId,
      anoExercicio: anoEx,
      registrosY540: y540,
      registrosY570: [...SEED_ECF_BLOCO_Y.registrosY570],
      registrosY600: y600,
      registroY672: {
        capitalSocialIntegralizado: 500000.00,
        comprasMercadoriasRevenda: 215000.00,
        comprasMateriasPrimas: 180000.00,
        folhaSalariosBruta: 294000.00,
        ativoTotalFinal: 1485000.00,
        saldoFinalCaixaBancos: 342500.00
      },
      dataAtualizacao: new Date().toISOString()
    };

    this.salvarEcfBlocoY(novoBlocoY);
    return novoBlocoY;
  }

  public gerarArquivoSpedEcfBlocoYTxt(dados: EcfBlocoYDados): string {
    const lines: string[] = [];
    lines.push(`|Y001|0|`);

    // Y540
    dados.registrosY540.forEach(y => {
      lines.push(`|Y540|${y.cnpjEstabelecimento.replace(/\D/g, '')}|${y.codigoCnae.replace(/\D/g, '')}|${y.receitaVendaBensProprios.toFixed(2)}|${y.receitaVendaBensRevenda.toFixed(2)}|${y.receitaPrestacaoServicos.toFixed(2)}|${y.receitaExportacao.toFixed(2)}|${y.outrasReceitasOperacionais.toFixed(2)}|${y.totalReceitaAtividade.toFixed(2)}|`);
    });

    // Y570
    dados.registrosY570.forEach(y => {
      const indOrg = y.orgaoPublico ? '1' : '2';
      lines.push(`|Y570|${y.cnpjFontePagadora.replace(/\D/g, '')}|${y.nomeFontePagadora.toUpperCase()}|${indOrg}|${y.codigoReceita}|${y.rendimentoBruto.toFixed(2)}|${y.irrfRetido.toFixed(2)}|${y.csllRetida.toFixed(2)}|`);
    });

    // Y600
    dados.registrosY600.forEach(y => {
      lines.push(`|Y600|${y.paisResidencia}|${y.indicadorPfPj}|${y.cpfCnpj.replace(/\D/g, '')}|${y.nomeSocioDirigente.toUpperCase()}|${y.qualificacaoSocio}|${y.percentualCapitalTotal.toFixed(2)}|${y.percentualCapitalVotante.toFixed(2)}|${y.rendimentoBrutoProlabore.toFixed(2)}|${y.lucrosDividendosPagos.toFixed(2)}|${y.jurosSobreCapitalProprio.toFixed(2)}|${y.demaisRendimentos.toFixed(2)}|${y.irrfRetidoSocio.toFixed(2)}|`);
    });

    // Y672
    const y672 = dados.registroY672;
    lines.push(`|Y672|${y672.capitalSocialIntegralizado.toFixed(2)}|${y672.comprasMercadoriasRevenda.toFixed(2)}|${y672.comprasMateriasPrimas.toFixed(2)}|${y672.folhaSalariosBruta.toFixed(2)}|${y672.ativoTotalFinal.toFixed(2)}|${y672.saldoFinalCaixaBancos.toFixed(2)}|`);

    lines.push(`|Y990|${lines.length + 1}|`);
    return lines.join('\r\n');
  }

