  // ==========================================
  public getFichasLocacaoDimob(empresaId?: number, ano?: number): FichaLocacaoDimob[] {
    const empId = empresaId || this.activeEmpresaId;
    const anoRef = ano || new Date().getFullYear();
    const list = this.fichasLocacaoDimob.filter(f => f.empresaId === empId && f.anoReferencia === anoRef);
    return list.length ? list : SEED_FICHAS_LOCACAO_DIMOB.filter(f => f.empresaId === empId && f.anoReferencia === anoRef);
  }

  public salvarFichaLocacaoDimob(ficha: FichaLocacaoDimob): void {
    const idx = this.fichasLocacaoDimob.findIndex(f => f.id === ficha.id);
    if (idx >= 0) {
      this.fichasLocacaoDimob[idx] = ficha;
    } else {
      this.fichasLocacaoDimob.push(ficha);
    }
    this.persistSnapshot();
  }

  public excluirFichaLocacaoDimob(id: string): void {
    this.fichasLocacaoDimob = this.fichasLocacaoDimob.filter(f => f.id !== id);
    this.persistSnapshot();
  }

  public getFichasIntermediacaoDimob(empresaId?: number, ano?: number): FichaIntermediacaoVendaDimob[] {
    const empId = empresaId || this.activeEmpresaId;
    const anoRef = ano || new Date().getFullYear();
    const list = this.fichasIntermediacaoDimob.filter(f => f.empresaId === empId && f.anoReferencia === anoRef);
    return list.length ? list : SEED_FICHAS_INTERMEDIACAO_DIMOB.filter(f => f.empresaId === empId && f.anoReferencia === anoRef);
  }

  public salvarFichaIntermediacaoDimob(ficha: FichaIntermediacaoVendaDimob): void {
    const idx = this.fichasIntermediacaoDimob.findIndex(f => f.id === ficha.id);
    if (idx >= 0) {
      this.fichasIntermediacaoDimob[idx] = ficha;
    } else {
      this.fichasIntermediacaoDimob.push(ficha);
    }
    this.persistSnapshot();
  }

  public excluirFichaIntermediacaoDimob(id: string): void {
    this.fichasIntermediacaoDimob = this.fichasIntermediacaoDimob.filter(f => f.id !== id);
    this.persistSnapshot();
  }

  public getDeclaracaoDimob(empresaId?: number, ano?: number): DeclaracaoDimob {
    const empId = empresaId || this.activeEmpresaId;
    const anoCal = ano || new Date().getFullYear();
    const locacoes = this.getFichasLocacaoDimob(empId, anoCal);
    const intermediacoes = this.getFichasIntermediacaoDimob(empId, anoCal);
    const emp = this.getEmpresa(empId);

    const totalLocBruto = locacoes.reduce((acc, l) => acc + l.totalAnualBruto, 0);
    const totalLocComissao = locacoes.reduce((acc, l) => acc + l.totalAnualComissao, 0);
    const totalVendas = intermediacoes.reduce((acc, v) => acc + v.valorTotalVenda, 0);
    const totalVendasComissao = intermediacoes.reduce((acc, v) => acc + v.valorComissaoImobiliaria, 0);

    const declaracao: DeclaracaoDimob = {
      empresaId: empId,
      anoCalendario: anoCal,
      anoReferencia: anoCal,
      retificadora: false,
      responsavelNome: emp?.responsavelLegal || 'Carlos Eduardo Mendes',
      responsavelCpf: emp?.cpfResponsavel || '321.654.987-00',
      fichasLocacao: locacoes,
      fichasIntermediacao: intermediacoes,
      totalGeralLocacoesBruto: totalLocBruto,
      totalGeralComissoesLocacao: totalLocComissao,
      totalGeralVendas: totalVendas,
      totalGeralComissoesVenda: totalVendasComissao,
      dataGeracao: new Date().toISOString()
    };

    declaracao.arquivoDimobTxt = this.gerarArquivoDimobTxt(declaracao);
    return declaracao;
  }

  public gerarArquivoDimobTxt(dec: DeclaracaoDimob): string {
    const lines: string[] = [];
    const emp = this.getEmpresa(dec.empresaId);
    const cnpjClean = (emp?.cnpj || '12345678000190').replace(/\D/g, '').padEnd(14, '0');
    const ano = dec.anoCalendario.toString();
    const retif = dec.retificadora ? 'S' : 'N';
    const recibo = (dec.numeroReciboAnterior || '').padEnd(10, ' ');

    // Header
    lines.push(`DIMOB|${ano}|${cnpjClean}|${(emp?.razaoSocial || 'EMPRESA').toUpperCase().slice(0, 60).padEnd(60, ' ')}|${retif}|${recibo}|`);

    // R01 - Dados do Declarante
    lines.push(`R01|${cnpjClean}|${(emp?.cpfResponsavel || '32165498700').replace(/\D/g, '')}|${(dec.responsavelNome || 'RESPONSAVEL').toUpperCase()}|${(emp?.telefone || '').replace(/\D/g, '')}|`);

    // R02 - Fichas de Locação
    dec.fichasLocacao.forEach((f, idx) => {
      const seq = (idx + 1).toString().padStart(5, '0');
      const valores12 = f.rendimentosMensais.map(m => `${m.rendimentoBruto.toFixed(2)};${m.valorComissao.toFixed(2)};${m.impostoRetidoFonte.toFixed(2)}`).join(';');
      lines.push(`R02|${seq}|${f.numeroContrato}|${f.dataContrato.replace(/-/g, '')}|${f.tipoImovel === 'URBANO' ? 'U' : 'R'}|${f.locadorCpfCnpj.replace(/\D/g, '')}|${f.locadorNome.toUpperCase()}|${f.locatarioCpfCnpj.replace(/\D/g, '')}|${f.locatarioNome.toUpperCase()}|${valores12}|`);
    });

    // R03 - Fichas de Intermediação
    dec.fichasIntermediacao.forEach((v, idx) => {
      const seq = (idx + 1).toString().padStart(5, '0');
      lines.push(`R03|${seq}|${v.numeroContrato}|${v.dataContrato.replace(/-/g, '')}|${v.vendedorCpfCnpj.replace(/\D/g, '')}|${v.vendedorNome.toUpperCase()}|${v.compradorCpfCnpj.replace(/\D/g, '')}|${v.compradorNome.toUpperCase()}|${v.dataTransacao.replace(/-/g, '')}|${v.valorTotalVenda.toFixed(2)}|${v.valorComissaoImobiliaria.toFixed(2)}|${v.numeroNotaFiscal || ''}|`);
    });

    // Trailer
    lines.push(`T9|${lines.length + 1}|`);
    return lines.join('\r\n');
  }

  public integrarDimobContabil(empresaId?: number, ano?: number): { sucesso: boolean; mensagem: string; numeroLote?: number } {
    const empId = empresaId || this.activeEmpresaId;
    const anoCal = ano || new Date().getFullYear();
    const dec = this.getDeclaracaoDimob(empId, anoCal);

    const totalComissoes = dec.totalGeralComissoesLocacao + dec.totalGeralComissoesVenda;
    if (totalComissoes <= 0) {
      return { sucesso: false, mensagem: 'Não há receitas de comissão/administração para integrar.' };
    }

    const loteId = Date.now();
    const dataHoje = new Date().toISOString().split('T')[0];

    // Lançamento: Débito em Clientes/Caixa e Crédito em Receita de Administração/Intermediação Imobiliária
    const offsetId = (empId - 1) * 100;
    const lanc: LancamentoContabil = {
      id: Date.now() + 1,
      empresaId: empId,
      loteId,
      numeroPartida: this.lancamentos.length + 1,
      dataLancamento: dataHoje,
      tipoPartida: 'SIMPLES',
      contaDebitoId: offsetId + 3, // Banco Conta Movimento
      contaCreditoId: offsetId + 42, // Receita de Serviços Prestados
      valor: totalComissoes,
      historicoId: 1,
      complementoHistorico: `Reconhecimento das Comissões e Receitas Imobiliárias apuradas na DIMOB ${anoCal} (Total R$ ${totalComissoes.toLocaleString('pt-BR', { minimumFractionDigits: 2 })})`,
      createdAt: new Date().toISOString()
    };

    this.lancamentos.unshift(lanc);
    this.persistSnapshot();

    return {
      sucesso: true,
      mensagem: `Integração DIMOB concluída! Receita de R$ ${totalComissoes.toLocaleString('pt-BR', { minimumFractionDigits: 2 })} lançada no Diário Geral com sucesso.`,
      numeroLote: loteId
    };
  }

