  public getServicosMedicosDmed(empresaId?: number, ano?: number): RegistroRopServicoMedico[] {
    const empId = empresaId || this.activeEmpresaId;
    const anoCal = ano || new Date().getFullYear();
    const list = this.servicosMedicosDmed.filter(s => s.empresaId === empId && s.anoCalendario === anoCal);
    return list.length ? list : SEED_SERVICOS_MEDICOS_DMED.filter(s => s.empresaId === empId && s.anoCalendario === anoCal);
  }

  public salvarServicoMedicoDmed(servico: RegistroRopServicoMedico): void {
    const idx = this.servicosMedicosDmed.findIndex(s => s.id === servico.id);
    if (idx >= 0) {
      this.servicosMedicosDmed[idx] = servico;
    } else {
      this.servicosMedicosDmed.push(servico);
    }
    this.persistSnapshot();
  }

  public excluirServicoMedicoDmed(id: string): void {
    this.servicosMedicosDmed = this.servicosMedicosDmed.filter(s => s.id !== id);
    this.persistSnapshot();
  }

  public getPlanosSaudeDmed(empresaId?: number, ano?: number): RegistroDdmPlanoSaude[] {
    const empId = empresaId || this.activeEmpresaId;
    const anoCal = ano || new Date().getFullYear();
    const list = this.planosSaudeDmed.filter(p => p.empresaId === empId && p.anoCalendario === anoCal);
    return list.length ? list : SEED_PLANOS_SAUDE_DMED.filter(p => p.empresaId === empId && p.anoCalendario === anoCal);
  }

  public salvarPlanoSaudeDmed(plano: RegistroDdmPlanoSaude): void {
    const idx = this.planosSaudeDmed.findIndex(p => p.id === plano.id);
    if (idx >= 0) {
      this.planosSaudeDmed[idx] = plano;
    } else {
      this.planosSaudeDmed.push(plano);
    }
    this.persistSnapshot();
  }

  public excluirPlanoSaudeDmed(id: string): void {
    this.planosSaudeDmed = this.planosSaudeDmed.filter(p => p.id !== id);
    this.persistSnapshot();
  }

  public getDeclaracaoDmed(empresaId?: number, ano?: number): DeclaracaoDmed {
    const empId = empresaId || this.activeEmpresaId;
    const anoCal = ano || new Date().getFullYear();
    const servicos = this.getServicosMedicosDmed(empId, anoCal);
    const planos = this.getPlanosSaudeDmed(empId, anoCal);
    const emp = this.getEmpresa(empId);

    const totalPago = servicos.reduce((acc, s) => acc + s.valorPago, 0);
    const totalReembolsado = servicos.reduce((acc, s) => acc + s.valorReembolsado, 0);
    const totalDedutivel = servicos.reduce((acc, s) => acc + s.valorDedutivel, 0);

    const declaracao: DeclaracaoDmed = {
      empresaId: empId,
      anoCalendario: anoCal,
      anoReferencia: anoCal,
      retificadora: false,
      responsavelNome: emp?.responsavelLegal || 'Carlos Eduardo Mendes',
      responsavelCpf: emp?.cpfResponsavel || '321.654.987-00',
      servicosPrestados: servicos,
      planosSaude: planos,
      totalValorPagoServicos: totalPago,
      totalValorReembolsado: totalReembolsado,
      totalValorDedutivel: totalDedutivel,
      dataGeracao: new Date().toISOString()
    };

    declaracao.arquivoDmedTxt = this.gerarArquivoDmedTxt(declaracao);
    return declaracao;
  }

  public gerarArquivoDmedTxt(dec: DeclaracaoDmed): string {
    const lines: string[] = [];
    const emp = this.getEmpresa(dec.empresaId);
    const cnpjClean = (emp?.cnpj || '12345678000190').replace(/\D/g, '').padEnd(14, '0');
    const ano = dec.anoCalendario.toString();
    const retif = dec.retificadora ? 'S' : 'N';
    const recibo = (dec.numeroReciboAnterior || '').padEnd(12, ' ');

    // Header
    lines.push(`DMED|${ano}|${ano}|${cnpjClean}|${(emp?.razaoSocial || 'CLINICA MEDICA').toUpperCase()}|${retif}|${recibo}|${(dec.responsavelNome || 'RESPONSAVEL').toUpperCase()}|${(dec.responsavelCpf || '').replace(/\D/g, '')}|`);

    // Registros ROP
    dec.servicosPrestados.forEach(s => {
      lines.push(`ROP|${s.responsavelCpf.replace(/\D/g, '')}|${s.responsavelNome.toUpperCase()}|${(s.beneficiarioCpf || '').replace(/\D/g, '')}|${s.beneficiarioNome.toUpperCase()}|${s.beneficiarioDataNascimento.replace(/-/g, '')}|${s.parentescoBeneficiario}|${s.tipoServicoSaude}|${s.profissionalCrmCro}|${s.valorPago.toFixed(2)}|${s.valorReembolsado.toFixed(2)}|${s.valorDedutivel.toFixed(2)}|`);
    });

    // Registros DDM
    dec.planosSaude.forEach(p => {
      lines.push(`DDM|${p.registroAnsOperadora}|${p.nomeOperadora.toUpperCase()}|${p.responsavelCpf.replace(/\D/g, '')}|${p.responsavelNome.toUpperCase()}|${p.numeroContrato}|${p.valorAnualPago.toFixed(2)}|${p.beneficiariosQtd}|`);
    });

    // Trailler
    lines.push(`FIMDMED|${lines.length + 1}|`);
    return lines.join('\r\n');
  }

  public integrarDmedContabil(empresaId?: number, ano?: number): { sucesso: boolean; mensagem: string; numeroLote?: number } {
    const empId = empresaId || this.activeEmpresaId;
    const anoCal = ano || new Date().getFullYear();
    const dec = this.getDeclaracaoDmed(empId, anoCal);

    if (dec.totalValorPagoServicos <= 0) {
      return { sucesso: false, mensagem: 'Não há receitas de serviços de saúde para integrar.' };
    }

    const loteId = Date.now();
    const dataHoje = new Date().toISOString().split('T')[0];
    const offsetId = (empId - 1) * 100;

    const lanc: LancamentoContabil = {
      id: Date.now() + 1,
      empresaId: empId,
      loteId,
      numeroPartida: this.lancamentos.length + 1,
      dataLancamento: dataHoje,
      tipoPartida: 'SIMPLES',
      contaDebitoId: offsetId + 3, // Banco Conta Movimento
      contaCreditoId: offsetId + 42, // Receita de Serviços Médicos e de Saúde
      valor: dec.totalValorPagoServicos,
      historicoId: 1,
      complementoHistorico: `Reconhecimento das Receitas de Serviços Médicos/Saúde declarados na DMED ${anoCal} (Total R$ ${dec.totalValorPagoServicos.toLocaleString('pt-BR', { minimumFractionDigits: 2 })})`,
      createdAt: new Date().toISOString()
    };

    this.lancamentos.unshift(lanc);
    this.persistSnapshot();

    return {
      sucesso: true,
      mensagem: `Integração DMED concluída! Receita de R$ ${dec.totalValorPagoServicos.toLocaleString('pt-BR', { minimumFractionDigits: 2 })} lançada no Diário Geral com sucesso.`,
      numeroLote: loteId
    };
  }

