  // --- 1. ZONA FRANCA DE MANAUS & BENEFÍCIOS SUFRAMA (Dec-Lei 288/67 / Lei 10.996/04) ---
  public getOperacoesSuframa(empresaId?: number): ResumoOperacoesSuframa {
    const empId = empresaId || this.activeEmpresaId;
    const lista = this.operacoesSuframa.filter(o => o.empresaId === empId);

    const totalOperacoes = lista.length;
    const totalFaturamentoBrutoBRL = lista.reduce((acc, o) => acc + o.valorTotalProdutosBRL, 0);
    const totalIcmsDesoneradoBRL = lista.reduce((acc, o) => acc + o.valorIcmsDesoneradoBRL, 0);
    const totalEconomiaPisCofinsBRL = lista.reduce((acc, o) => acc + o.valorEconomiaPisBRL + o.valorEconomiaCofinsBRL, 0);
    const totalOperacoesInternadas = lista.filter(o => o.statusPin === 'VISTORIADO_INTERNADO').length;

    return {
      empresaId: empId,
      totalOperacoes,
      totalFaturamentoBrutoBRL,
      totalIcmsDesoneradoBRL,
      totalEconomiaPisCofinsBRL,
      totalOperacoesInternadas,
      operacoes: lista
    };
  }

