  // --- 3. CESSÃO DE MÃO DE OBRA & RETENÇÕES EM SUBCONTRATAÇÃO (Lei 8.212/91 / IN RFB 2.110/22) ---
  public getRetencoesMaoDeObra(empresaId?: number): ResumoRetencoesMaoDeObra {
    const empId = empresaId || this.activeEmpresaId;
    const lista = this.retencoesMaoDeObra.filter(r => r.empresaId === empId);

    const totalNotas = lista.length;
    const totalValorBrutoBRL = lista.reduce((acc, r) => acc + r.valorBrutoNotaBRL, 0);
    const totalDeducoesLegaisBRL = lista.reduce((acc, r) => acc + r.valorDeducaoMateriaisEquipamentosBRL + r.valorDeducaoSubcontratacaoBRL, 0);
    const totalBaseCalculoBRL = lista.reduce((acc, r) => acc + r.baseCalculoInssRetencaoBRL, 0);
    const totalInssRetidoBRL = lista.reduce((acc, r) => acc + r.valorInssRetidoCalculadoBRL, 0);

    return {
      empresaId: empId,
      totalNotas,
      totalValorBrutoBRL,
      totalDeducoesLegaisBRL,
      totalBaseCalculoBRL,
      totalInssRetidoBRL,
      notas: lista
    };
  }

