  public getEcdBlocoJ(empresaId?: number, anoCalendario?: number): ResumoEcdBlocoJ {
    const empId = empresaId || this.activeEmpresaId;
    const ano = anoCalendario || 2026;

    let dec = this.declaracoesEcdBlocoJ.find(d => d.empresaId === empId && d.anoCalendario === ano);
    if (!dec && empId === 1) {
      dec = SEED_DECLARACOES_ECD_BLOCO_J[0];
      this.declaracoesEcdBlocoJ.push(dec);
      this.persistSnapshot();
    }

    if (!dec) {
      dec = {
        id: `ecd-bloco-j-${ano}-emp${empId}`,
        empresaId: empId,
        anoCalendario: ano,
        dataInicioPeriodo: `${ano}-01-01`,
        dataFimPeriodo: `${ano}-12-31`,
        identificadorDemonstracao: '1 - Balanço Geral e DRE Anual',
        cabecalhoJ005Descricao: `Demonstrações Contábeis Encerradas em 31/12/${ano}`,
        linhasJ100: SEED_DECLARACOES_ECD_BLOCO_J[0].linhasJ100,
        linhasJ150: SEED_DECLARACOES_ECD_BLOCO_J[0].linhasJ150,
        linhasJ210: SEED_DECLARACOES_ECD_BLOCO_J[0].linhasJ210,
        signatariosJ930: SEED_DECLARACOES_ECD_BLOCO_J[0].signatariosJ930,
        termoEncerramentoJ900: SEED_DECLARACOES_ECD_BLOCO_J[0].termoEncerramentoJ900,
        totalLinhasBlocoJ: 35,
        statusValidacao: 'CONFORME'
      };
      this.declaracoesEcdBlocoJ.push(dec);
      this.persistSnapshot();
    }

    const ativo = dec.linhasJ100.find(l => l.codigoAglutinacao === '1')?.valorSaldoFinal || 0;
    const passivoPl = dec.linhasJ100.find(l => l.codigoAglutinacao === '2')?.valorSaldoFinal || 0;
    const diferenca = Math.abs(ativo - passivoPl);
    const resultado = dec.linhasJ150.find(l => l.indicadorGrupoDRE === 'LUCRO_LIQUIDO')?.valorSaldoFinal || 0;

    return {
      declaracao: dec,
      totalAtivo: ativo,
      totalPassivoPl: passivoPl,
      diferencaAtivoPassivo: diferenca,
      resultadoLiquidoExercicio: resultado
    };
  }

  public salvarDeclaracaoEcdBlocoJ(declaracao: DeclaracaoEcdBlocoJ): { sucesso: boolean; mensagem: string } {
    const idx = this.declaracoesEcdBlocoJ.findIndex(d => d.id === declaracao.id);
    if (idx >= 0) {
      this.declaracoesEcdBlocoJ[idx] = declaracao;
    } else {
      this.declaracoesEcdBlocoJ.push(declaracao);
    }
    this.persistSnapshot();
    return { sucesso: true, mensagem: `Demonstrações Contábeis da ECD (Bloco J) salvas com sucesso.` };
  }

  public validarConsistenciaEcd(declaracaoId: string): { sucesso: boolean; mensagem: string; valido: boolean; erros: string[] } {
    const dec = this.declaracoesEcdBlocoJ.find(d => d.id === declaracaoId);
    if (!dec) return { sucesso: false, mensagem: 'Declaração da ECD não localizada.', valido: false, erros: ['Declaração inexistente.'] };

    const erros: string[] = [];
    const ativo = dec.linhasJ100.find(l => l.codigoAglutinacao === '1')?.valorSaldoFinal || 0;
    const passivoPl = dec.linhasJ100.find(l => l.codigoAglutinacao === '2')?.valorSaldoFinal || 0;

    if (Math.abs(ativo - passivoPl) > 0.01) {
      erros.push(`Equação Fundamental violada: Ativo Total (R$ ${ativo.toFixed(2)}) diverge de Passivo+PL Total (R$ ${passivoPl.toFixed(2)}).`);
    }

    const temContador = dec.signatariosJ930.some(s => s.qualificacao.includes('Contador') && s.numeroInscricaoCrc);
    if (!temContador) {
      erros.push('Registro J930: É obrigatória a identificação de ao menos um Contador com CRC ativo.');
    }

    const temAdmin = dec.signatariosJ930.some(s => s.qualificacao.includes('Diretor') || s.qualificacao.includes('Administrador'));
    if (!temAdmin) {
      erros.push('Registro J930: É obrigatória a identificação do Administrador / Diretor representante legal.');
    }

    const valido = erros.length === 0;
    dec.statusValidacao = valido ? 'CONFORME' : 'DIVERGENCIA_BALANCO';
    this.persistSnapshot();

    return {
      sucesso: true,
      mensagem: valido ? 'Bloco J validado com sucesso! Nenhuma inconsistência encontrada para o PVA do SPED Contábil.' : 'Inconsistências encontradas nas Demonstrações.',
      valido,
      erros
    };
  }

  public gerarArquivoSpedEcdTxt(declaracaoId: string): { sucesso: boolean; mensagem: string; arquivoTxt?: string; nomeArquivo?: string } {
    const dec = this.declaracoesEcdBlocoJ.find(d => d.id === declaracaoId);
    if (!dec) return { sucesso: false, mensagem: 'Declaração da ECD não localizada.' };

    const emp = this.getActiveEmpresa();
    const cnpj = emp.cnpj.replace(/\D/g, '');
    const dtIni = dec.dataInicioPeriodo.replace(/-/g, '');
    const dtFim = dec.dataFimPeriodo.replace(/-/g, '');

    const lines: string[] = [];
    lines.push(`|J001|0|`);
    lines.push(`|J005|${dtIni}|${dtFim}|1|${dec.cabecalhoJ005Descricao}|`);

    dec.linhasJ100.forEach(l => {
      lines.push(`|J100|${l.codigoAglutinacao}|${l.nivel}|${l.tipoConta}|${l.descricao}|${l.valorSaldoFinal.toFixed(2)}|${l.indicadorDcFinal}|${l.notaExplicativaRef || ''}|`);
    });

    dec.linhasJ150.forEach(l => {
      lines.push(`|J150|${l.codigoAglutinacao}|${l.nivel}|${l.tipoConta}|${l.descricao}|${l.valorSaldoFinal.toFixed(2)}|${l.indicadorDcFinal}|`);
    });

    dec.linhasJ210.forEach(l => {
      lines.push(`|J210|${l.codigoAglutinacao}|${l.descricaoFato}|${l.saldoInicial.toFixed(2)}|${l.saldoFinal.toFixed(2)}|`);
    });

    lines.push(`|J900|${dec.termoEncerramentoJ900}|`);

    dec.signatariosJ930.forEach(s => {
      const qualifCode = s.qualificacao.split(' ')[0];
      lines.push(`|J930|${s.nome}|${s.cpf.replace(/\D/g, '')}|${qualifCode}|${s.numeroInscricaoCrc || ''}|${s.email}|${s.telefone}|`);
    });

    lines.push(`|J990|${lines.length + 1}|`);

    const arquivoTxt = lines.join('\r\n');
    const nomeArquivo = `SPED_ECD_BLOCO_J_${cnpj}_${dec.anoCalendario}.txt`;

    return {
      sucesso: true,
      mensagem: `Arquivo Bloco J do SPED Contábil gerado no padrão oficial Leiaute 9.`,
      arquivoTxt,
      nomeArquivo
    };
  }

