  public getApuracaoIpiSelos(empresaId?: number, competencia?: string): ResumoApuracaoIpiSelos {
    const empId = empresaId || this.activeEmpresaId;
    const comp = competencia || '2026-03';

    let apuracao = this.apuracoesIpiModelo8.find(a => a.empresaId === empId && a.competencia === comp);
    if (!apuracao && empId === 1) {
      apuracao = SEED_APURACOES_IPI_MODELO8[0];
      this.apuracoesIpiModelo8.push(apuracao);
      this.persistSnapshot();
    }

    if (!apuracao) {
      apuracao = {
        id: `ipi-mod8-emp${empId}-${comp.replace('-', '')}`,
        empresaId: empId,
        competencia: comp,
        periodoApuracao: 'MENSAL',
        numeroLivro: 1,
        folhaInicial: 1,
        folhaFinal: 3,
        dataUltimoLancamento: `${comp}-28`,
        totalDebitosSaidas: 0,
        outrosDebitos: 0,
        estornoCreditos: 0,
        totalGeralDebitos: 0,
        totalCreditosEntradas: 0,
        outrosCreditos: 0,
        estornoDebitos: 0,
        saldoCredorAnterior: 0,
        totalGeralCreditos: 0,
        saldoDevedorRecolher: 0,
        saldoCredorTransportar: 0,
        codigoReceitaDarf: '5123',
        vencimentoDarf: `${comp}-25`,
        dataEncerramento: `${comp}-28`,
        status: 'ABERTA',
        itens: []
      };
      this.apuracoesIpiModelo8.push(apuracao);
      this.persistSnapshot();
    }

    let selos = this.selosControleIpi.filter(s => s.empresaId === empId);
    if (!selos.length && empId === 1) {
      selos = [...SEED_SELOS_CONTROLE_IPI];
      this.selosControleIpi.push(...selos);
      this.persistSnapshot();
    }

    const totalDisponiveis = selos.reduce((acc, s) => acc + s.saldoFinal, 0);
    const totalAplicados = selos.reduce((acc, s) => acc + s.saidasAplicacao, 0);
    const totalAvarias = selos.reduce((acc, s) => acc + s.perdasAvarias, 0);

    return {
      empresaId: empId,
      competencia: comp,
      apuracao,
      selos,
      totalSelosDisponiveis: totalDisponiveis,
      totalSelosAplicados: totalAplicados,
      totalAvarias: totalAvarias
    };
  }

  public salvarItemSeloControle(item: ItemSeloControle): { sucesso: boolean; mensagem: string } {
    const idx = this.selosControleIpi.findIndex(s => s.id === item.id);
    if (idx >= 0) {
      this.selosControleIpi[idx] = item;
    } else {
      this.selosControleIpi.push(item);
    }
    this.persistSnapshot();
    return { sucesso: true, mensagem: `Cadastro de Selo de Controle '${item.descricao}' salvo com sucesso.` };
  }

  public lancarMovimentoSelo(seloId: string, mov: MovimentoSeloControle): { sucesso: boolean; mensagem: string } {
    const selo = this.selosControleIpi.find(s => s.id === seloId);
    if (!selo) return { sucesso: false, mensagem: 'Item de Selo de Controle não localizado.' };

    selo.movimentacoes.push(mov);

    if (mov.tipoMovimentacao === 'ENTRADA_REQUISICAO_RFB') {
      selo.entradasMes += mov.quantidade;
      selo.saldoFinal += mov.quantidade;
    } else if (mov.tipoMovimentacao === 'SAIDA_APLICACAO_PRODUCAO') {
      selo.saidasAplicacao += mov.quantidade;
      selo.saldoFinal -= mov.quantidade;
    } else if (mov.tipoMovimentacao === 'PERDA_AVARIA_QUEBRA') {
      selo.perdasAvarias += mov.quantidade;
      selo.saldoFinal -= mov.quantidade;
    }

    this.persistSnapshot();
    return { sucesso: true, mensagem: `Movimentação de ${mov.quantidade} selos lançada com sucesso.` };
  }

  public salvarApuracaoIpiModelo8(apuracao: ApuracaoIpiModelo8): { sucesso: boolean; mensagem: string } {
    const idx = this.apuracoesIpiModelo8.findIndex(a => a.id === apuracao.id);
    if (idx >= 0) {
      this.apuracoesIpiModelo8[idx] = apuracao;
    } else {
      this.apuracoesIpiModelo8.push(apuracao);
    }
    this.persistSnapshot();
    return { sucesso: true, mensagem: `Livro Registro de Apuração do IPI (Modelo 8) comp. ${apuracao.competencia} salvo com sucesso.` };
  }

  public integrarIpiModelo8Contabil(apuracaoId: string): { sucesso: boolean; mensagem: string; loteId?: number } {
    const apuracao = this.apuracoesIpiModelo8.find(a => a.id === apuracaoId);
    if (!apuracao) return { sucesso: false, mensagem: 'Apuração do IPI não localizada.' };

    const loteId = Date.now();
    const dataHoje = new Date().toISOString().split('T')[0];
    const offsetId = (apuracao.empresaId - 1) * 100;

    // 1. D: IPI a Recolher (Passivo) / C: IPI a Recuperar (Ativo) -> Compensação dos Créditos
    const lancComp: LancamentoContabil = {
      id: Date.now() + 1,
      empresaId: apuracao.empresaId,
      loteId,
      numeroPartida: this.lancamentos.length + 1,
      dataLancamento: dataHoje,
      tipoPartida: 'SIMPLES',
      contaDebitoId: offsetId + 25, // IPI a Recolher (Passivo)
      contaCreditoId: offsetId + 15, // IPI a Recuperar (Ativo)
      valor: apuracao.totalGeralCreditos,
      historicoId: 1,
      complementoHistorico: `Compensação de Créditos de IPI da Apuração Modelo 8 comp. ${apuracao.competencia}`,
      createdAt: new Date().toISOString()
    };

    this.lancamentos.unshift(lancComp);
    apuracao.status = 'INTEGRADA_CONTABILIDADE';
    this.persistSnapshot();

    return {
      sucesso: true,
      mensagem: `Apuração do IPI comp. ${apuracao.competencia} integrada contabilmente no Diário Geral (Lote #${loteId}) com compensação de R$ ${apuracao.totalGeralCreditos.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}.`,
      loteId
    };
  }

  // =================================================================
  // SPRINT 52: eSocial SST (S-2220 / S-2240) - SAÚDE E SEGURANÇA DO TRABALHO
  // Portaria Conjunta MTP/RFB nº 02/2021, NR-07, NR-09, IN INSS nº 128/2022
  // Schemas Oficiais evtMonit.xsd & evtExpRisco.xsd (v_S_01_03_00)
  // =================================================================

  public getSstESocial(empresaId: number, competencia: string): ResumoSstESocial {
    const anoMes = competencia.slice(0, 7);
    const asos = this.eventosAsoS2220.filter(a => a.empresaId === empresaId);
    const condicoesAmbientais = this.eventosCondicoesS2240.filter(c => c.empresaId === empresaId);

    const totalExpostosRiscoEspecial = condicoesAmbientais.filter(c => c.codigoOcorrenciaGfip && c.codigoOcorrenciaGfip.trim() !== '').length;
    const totalSemRisco = condicoesAmbientais.filter(c => !c.codigoOcorrenciaGfip || c.codigoOcorrenciaGfip.trim() === '').length;

    return {
      empresaId,
      competencia: anoMes,
      asos,
      condicoesAmbientais,
      totalAsosRegistrados: asos.length,
      totalLaudosAmbientais: condicoesAmbientais.length,
      totalExpostosRiscoEspecial,
      totalSemRisco
    };
  }

