  public getCatESocial(empresaId: number, competencia: string): ResumoCatESocial {
    const catsEmpresa = this.eventosCatS2210.filter(c => c.empresaId === empresaId);
    const totalCats = catsEmpresa.length;
    const totalAcidentesTipicos = catsEmpresa.filter(c => c.tipoAcidente === '1_TIPICO').length;
    const totalAcidentesTrajeto = catsEmpresa.filter(c => c.tipoAcidente === '3_TRAJETO').length;
    const totalDoencasTrabalho = catsEmpresa.filter(c => c.tipoAcidente === '2_DOENCA').length;
    const totalComAfastamento = catsEmpresa.filter(c => c.atestadoMedico.houveAfastamento).length;

    return {
      empresaId,
      competencia,
      cats: catsEmpresa,
      totalCats,
      totalAcidentesTipicos,
      totalAcidentesTrajeto,
      totalDoencasTrabalho,
      totalComAfastamento
    };
  }

