  public getEventosPeriodicosFolhaS1260S1280(empresaId: number, competencia: string): ResumoEventosPeriodicosFolhaS1260S1280 {
    const rural = this.comercializacaoRuralS1260.filter(r => r.empresaId === empresaId && r.competencia === competencia);
    const avulsos = this.avulsosS1270.filter(a => a.empresaId === empresaId && a.competencia === competencia);
    const info = this.infoComplementaresS1280.find(i => i.empresaId === empresaId && i.competencia === competencia) || {
      id: `info-1280-${empresaId}-${competencia}`,
      empresaId,
      competencia,
      indicativoDesoneracaoCprb: '0_NAO_DESONERADA',
      fatorProporcionalidadeReducao: 0,
      receitaBrutaAtividadesDesoneradasBRL: 0,
      receitaBrutaTotalEmpresaBRL: 0,
      reducaoAliquotaPatronalCalculada: 0,
      indicativoAcordoInternacionalIsencao: false,
      statusTransmissao: 'PENDENTE'
    };

    const totalValorProducaoRuralBRL = rural.reduce((a, b) => a + (b.valorBrutoProducaoBRL || 0), 0);
    const totalFunruralRecolherBRL = rural.reduce((a, b) => a + (b.totalContribuicaoDevidaBRL || 0), 0);
    const totalRemuneracaoAvulsosBRL = avulsos.reduce((a, b) => a + (b.valorBrutoRemuneracaoAvulsosBRL || 0), 0);
    const totalEncargosAvulsosBRL = avulsos.reduce((a, b) => a + (b.valorEncargoPatronalBRL || 0), 0);

    return {
      empresaId,
      competencia,
      rural,
      avulsos,
      infoComplementar: info,
      totalValorProducaoRuralBRL,
      totalFunruralRecolherBRL,
      totalRemuneracaoAvulsosBRL,
      totalEncargosAvulsosBRL
    };
  }

